#!/usr/bin/env python3
"""Classify the quotient of source words by the full exact evaluation kernel."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=ROOT/'research'/'benincasa'/'results'
composition=json.loads((R/'cosmology_physical_boundary_exact_composition.json').read_text());transport=json.loads((R/'cosmology_physical_boundary_exact_transport_domain.json').read_text());assert composition['strict_coefficient_matches']==48 and transport['all_transport_domains_defined']
out={'schema':'marici.benincasa.cosmology-evaluation-quotient-recurrence-gate.v1','source_module':'descriptor-labelled rational T+S_K words at one ambient cutoff','evaluation_map':'source word -> sparse relation-row combination','quotient':'source module / kernel(evaluation)','canonical_identification':'the quotient is canonically isomorphic to image(evaluation)','faithful_coordinate_on_quotient':'the evaluated sparse row','finite_boundary_classes':{'A12_to_A14':48,'A14_to_A16':60,'A12_to_A16':48,'direct_composite_classes_equal':True},'composition_reason':'q-word differences telescope under admitted descriptor transport; equality in the evaluation quotient follows from equality of their evaluated boundary rows','information_lost':'all source-syzygy and correction-capability distinctions inside the evaluation kernel','unbounded_promotion':False,'promotion_failure':'the quotient presupposes that a later q-word boundary has a source lift; it cannot prove existence or exactness of new A18 targets','decision':'The full evaluation-kernel quotient is canonical and faithful on its quotient, but its recurrence is tautological and nonpromoting.','passed':True};(R/'cosmology_evaluation_quotient_recurrence_gate.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
